import{D as e}from"./index-BbvXgB4H.js";var t=`docs/references/hsk/sources/hsk3.pdf`,n=(e,n)=>`${t}#printed-pages=${e}&pdf-pages=${n}`,r=n(`144-153`,`156-165`),i=t=>({image:e(`/assets/group3/lesson-hsk3-l16-${t}-v1.webp`),imageSrcSet:`${e(`/assets/group3/lesson-hsk3-l16-${t}-720w-v1.webp`)} 720w, ${e(`/assets/group3/lesson-hsk3-l16-${t}-v1.webp`)} 1400w`}),a=(e,t)=>({...t,reading:t.pinyin,sourceRef:e}),o=(e,t,n)=>({zh:e,th:t,focus:n}),s=[[1,`脏`,`zāng`,`adj.`,`dirty`,`สกปรก`,146,158],[2,`可爱`,`kě'ài`,`adj.`,`cute; lovely`,`น่ารัก`,146,158],[3,`一会儿`,`yíhuìr`,`adv.`,`a moment; now...then...`,`ครู่หนึ่ง / เดี๋ยว...เดี๋ยว...`,146,158],[4,`脚`,`jiǎo`,`n.`,`foot`,`เท้า`,146,158],[5,`照顾`,`zhàogù`,`v.`,`take care of`,`ดูแล`,146,158],[6,`好像`,`hǎoxiàng`,`v.`,`seem; be like`,`ดูเหมือน`,146,158],[7,`认得`,`rènde`,`v.`,`recognize`,`จำได้ / รู้จัก`,146,158],[8,`周末`,`zhōumò`,`n.`,`weekend`,`สุดสัปดาห์`,146,158],[9,`动物园`,`dòngwùyuán`,`n.`,`zoo`,`สวนสัตว์`,146,158],[10,`动物`,`dòngwù`,`n.`,`animal`,`สัตว์`,146,158],[11,`大熊猫`,`dàxióngmāo`,`n.`,`giant panda`,`แพนด้ายักษ์`,147,159],[12,`奇怪`,`qíguài`,`adj.`,`strange`,`แปลก`,147,159],[13,`其实`,`qíshí`,`adv.`,`actually`,`ที่จริง`,147,159],[14,`竹子`,`zhúzi`,`n.`,`bamboo`,`ไผ่`,147,159],[15,`国宝`,`guóbǎo`,`n.`,`national treasure`,`สมบัติของชาติ`,147,159],[16,`全`,`quán`,`adj.`,`whole; entire`,`ทั้งหมด`,147,159],[17,`野生`,`yěshēng`,`adj.`,`wild`,`ตามธรรมชาติ`,147,159],[18,`关于`,`guānyú`,`prep.`,`about`,`เกี่ยวกับ`,147,159],[19,`饱`,`bǎo`,`adj.`,`full`,`อิ่ม`,149,161],[20,`张`,`zhāng`,`v.`,`open`,`อ้า / เปิด`,149,161],[21,`嘴`,`zuǐ`,`n.`,`mouth`,`ปาก`,149,161],[22,`身边`,`shēnbiān`,`n.`,`one's side`,`ข้างตัว`,149,161],[23,`半天`,`bàntiān`,`num.-m.`,`quite a while`,`ครึ่งวัน / ตั้งนาน`,149,161],[24,`脸`,`liǎn`,`n.`,`face`,`ใบหน้า`,149,161]].map(([e,t,r,i,a,o,s,c])=>({index:e,hanzi:t,pinyin:r,type:i,en:a,th:o,thAid:o,page:s,translationKind:`editorial-aid`,sourceRef:n(String(s),String(c))})),c=n(`145-146`,`157-158`),l=n(`147`,`159`),u=n(`148-149`,`160-161`),d={liuXiaoxue:{hanzi:`刘小雪`,pinyin:`Liú Xiǎoxuě`,nameTh:`หลิวเสี่ยวเสวี่ย`,nameEn:`Liu Xiaoxue`,...i(`pet-center`),imageFocus:`30% center`},liuXiaoming:{hanzi:`刘小明`,pinyin:`Liú Xiǎomíng`,nameTh:`หลิวเสี่ยวหมิง`,nameEn:`Liu Xiaoming`,...i(`zoo`),imageFocus:`30% center`},wang:{hanzi:`王一雪`,pinyin:`Wáng Yìxuě`,nameTh:`หวังอี้เสวี่ย`,nameEn:`Wang Yixue`,...i(`panda-house`),imageFocus:`66% center`},petWorker:{hanzi:`服务员`,pinyin:`Fúwùyuán`,nameTh:`เจ้าหน้าที่`,nameEn:`Attendant`,...i(`pet-center`),imageFocus:`70% center`}},f=[{id:`h3l16-pet-center`,number:`01`,glyph:`猫`,title:`小猫认得我们`,titleTh:`ลูกแมวจำพวกเราได้`,titleEn:`The cat recognizes us`,place:`宠物领养店`,placeTh:`ศูนย์รับเลี้ยงสัตว์`,...i(`pet-center`),source:`Text 1 · หน้าเล่ม 145–146 · PDF หน้า 157–158`,sourcePage:`145-146`,sourceRef:c,imageAlt:{zh:`宠物领养店小猫`,th:`ลูกแมวในศูนย์รับเลี้ยงสัตว์`,en:`A cat at the pet adoption center`},context:`在一家宠物领养店，王一雪和孩子们在看动物。`,contextTh:`ที่ศูนย์รับเลี้ยงสัตว์ หวังอี้เสวี่ยกับลูก ๆ กำลังดูสัตว์`,contextEn:`At a pet adoption center, Wang Yixue and the children were looking at animals.`,characters:[{role:`A`,profile:`liuXiaoxue`,noteZh:`喜欢小猫的孩子`,noteTh:`เด็กที่ชอบลูกแมว`,noteEn:`The child who likes the cat`},{role:`B`,profile:`petWorker`,noteZh:`照顾小猫的服务员`,noteTh:`เจ้าหน้าที่ผู้ดูแลลูกแมว`,noteEn:`The attendant caring for the cat`},{role:`C`,profile:`wang`,noteZh:`考虑能否领养的妈妈`,noteTh:`แม่ที่พิจารณาการรับเลี้ยง`,noteEn:`The mother considering adoption`}],lines:[a(c,{role:`A`,speaker:`刘小雪`,hanzi:`这只小猫你们养了多久了？`,pinyin:`Zhè zhī xiǎomāo nǐmen yǎng le duō jiǔ le?`,en:`How long have you kept this kitten?`,th:`พวกคุณเลี้ยงลูกแมวตัวนี้มานานเท่าไรแล้ว?`,visual:o(`养了多久`,`เลี้ยงมานานเท่าไร`,`30% center`)}),a(c,{role:`B`,speaker:`服务员`,hanzi:`已经一年多了。第一天看见它的时候，它又脏又小。`,pinyin:`Yǐjīng yì nián duō le. Dì-yī tiān kànjiàn tā de shíhou, tā yòu zāng yòu xiǎo.`,en:`More than a year. When we first saw it, it was dirty and tiny.`,th:`กว่าหนึ่งปีแล้ว วันแรกที่เห็นมัน ทั้งสกปรกทั้งตัวเล็ก`,visual:o(`又脏又小`,`ทั้งสกปรกทั้งตัวเล็ก`,`70% center`)}),a(c,{role:`A`,speaker:`刘小雪`,hanzi:`现在它变得又干净又漂亮了。`,pinyin:`Xiànzài tā biàn de yòu gānjìng yòu piàoliang le.`,en:`Now it has become clean and beautiful.`,th:`ตอนนี้มันทั้งสะอาดทั้งสวยแล้ว`,visual:o(`又干净又漂亮`,`ทั้งสะอาดทั้งสวย`,`32% center`)}),a(c,{role:`B`,speaker:`服务员`,hanzi:`是啊。它还特别可爱，一会儿在你脚边睡觉，一会儿在你身上爬。`,pinyin:`Shì a. Tā hái tèbié kě'ài, yíhuìr zài nǐ jiǎo biān shuìjiào, yíhuìr zài nǐ shēn shang pá.`,en:`Yes. It is especially cute: one moment it sleeps by your feet, the next it climbs on you.`,th:`ใช่ มันน่ารักมาก เดี๋ยวนอนข้างเท้า เดี๋ยวปีนบนตัวคุณ`,visual:o(`一会儿睡觉一会儿爬`,`เดี๋ยวนอนเดี๋ยวปีน`,`68% center`)}),a(c,{role:`A`,speaker:`刘小雪`,hanzi:`你们把它照顾得真好。`,pinyin:`Nǐmen bǎ tā zhàogù de zhēn hǎo.`,en:`You have taken such good care of it.`,th:`พวกคุณดูแลมันดีจริง ๆ`,visual:o(`照顾得真好`,`ดูแลดีจริง ๆ`,`34% center`)}),a(c,{role:`B`,speaker:`服务员`,hanzi:`它就好像我们的孩子，我们照顾它，它也认得我们了。`,pinyin:`Tā jiù hǎoxiàng wǒmen de háizi, wǒmen zhàogù tā, tā yě rènde wǒmen le.`,en:`It is like our child. We care for it, and now it recognizes us.`,th:`มันเหมือนลูกของเรา เราดูแลมัน และมันก็จำเราได้แล้ว`,visual:o(`它也认得我们`,`มันก็จำเราได้`,`66% center`)}),a(c,{role:`A`,speaker:`刘小雪`,hanzi:`妈妈，我们家也养一只小猫吧。`,pinyin:`Māma, wǒmen jiā yě yǎng yì zhī xiǎomāo ba.`,en:`Mom, let us keep a kitten too.`,th:`แม่ บ้านเราเลี้ยงลูกแมวสักตัวเถอะ`,visual:o(`也养一只小猫`,`เลี้ยงลูกแมวสักตัว`,`36% center`)}),a(c,{role:`C`,speaker:`王一雪`,hanzi:`咱们没时间照顾，还是别养了，我周末带你们去北京动物园看动物吧。`,pinyin:`Zánmen méi shíjiān zhàogù, háishi bié yǎng le, wǒ zhōumò dài nǐmen qù Běijīng Dòngwùyuán kàn dòngwù ba.`,en:`We have no time to care for one, so we should not adopt it. I will take you to Beijing Zoo this weekend.`,th:`เราไม่มีเวลาดูแล อย่าเลี้ยงเลย สุดสัปดาห์แม่พาไปดูสัตว์ที่สวนสัตว์ปักกิ่ง`,visual:o(`周末去动物园`,`สุดสัปดาห์ไปสวนสัตว์`,`64% center`)})],qte:{after:3,prompt:{zh:`服务员第一次看见小猫时，它是什么样的？`,th:`ตอนเจ้าหน้าที่เห็นลูกแมวครั้งแรก มันเป็นอย่างไร?`,en:`What was the kitten like when the attendant first saw it?`},options:[{value:`又脏又小`,zh:`又脏又小`,pinyin:`yòu zāng yòu xiǎo`,th:`ทั้งสกปรกทั้งเล็ก`},{value:`又干净又漂亮`,zh:`又干净又漂亮`,pinyin:`yòu gānjìng yòu piàoliang`,th:`ทั้งสะอาดทั้งสวย`},{value:`又大又胖`,zh:`又大又胖`,pinyin:`yòu dà yòu pàng`,th:`ทั้งใหญ่ทั้งอ้วน`}],correct:`又脏又小`,evidence:`服务员：第一天看见它的时候，它又脏又小。`,evidenceTh:`เจ้าหน้าที่: วันแรกที่เห็นมัน ทั้งสกปรกทั้งตัวเล็ก`,sourceRef:c},builder:{prompt:{zh:`重组“一会儿……一会儿……”句`,th:`เรียงประโยคสลับการกระทำ`,en:`Rebuild the alternating-action sentence`},answer:[`它`,`一会儿在你脚边睡觉`,`一会儿`,`在你身上爬`],tiles:[`在你身上爬`,`一会儿`,`它`,`一会儿在你脚边睡觉`],gloss:{它:`มัน`,一会儿在你脚边睡觉:`เดี๋ยวนอนข้างเท้าคุณ`,一会儿:`อีกเดี๋ยว`,在你身上爬:`ปีนบนตัวคุณ`},translationTh:`มันเดี๋ยวนอนข้างเท้าคุณ เดี๋ยวปีนบนตัวคุณ`,translationEn:`One moment it sleeps by your feet; the next it climbs on you.`,evidence:`Text 1 · หน้าเล่ม 145`,sourceRef:c}},{id:`h3l16-zoo`,number:`02`,glyph:`宝`,title:`大熊猫是国宝`,titleTh:`แพนด้ายักษ์คือสมบัติของชาติ`,titleEn:`Giant pandas are a national treasure`,place:`动物园`,placePy:`dòngwùyuán`,placeTh:`สวนสัตว์`,...i(`zoo`),source:`Text 2 · หน้าเล่ม 147 · PDF หน้า 159`,sourcePage:`147`,sourceRef:l,imageAlt:{zh:`北京动物园`,th:`สวนสัตว์ปักกิ่ง`,en:`Beijing Zoo`},context:`在动物园，王一雪和孩子们边走边聊。`,contextTh:`ในสวนสัตว์ หวังอี้เสวี่ยกับลูก ๆ เดินไปคุยไป`,contextEn:`At the zoo, Wang Yixue and her children talked while walking.`,characters:[{role:`A`,profile:`liuXiaoming`,noteZh:`爱问问题的孩子`,noteTh:`เด็กที่ชอบถามคำถาม`,noteEn:`The curious child`},{role:`B`,profile:`wang`,noteZh:`回答问题的妈妈`,noteTh:`แม่ที่ตอบคำถาม`,noteEn:`The mother answering`},{role:`C`,profile:`liuXiaoxue`,noteZh:`提醒弟弟的姐姐`,noteTh:`พี่สาวที่แซวน้อง`,noteEn:`The sister teasing him`}],lines:[a(l,{role:`A`,speaker:`刘小明`,hanzi:`妈妈，大熊猫这个名字很奇怪，它们跟猫有什么关系？`,pinyin:`Māma, dàxióngmāo zhège míngzi hěn qíguài, tāmen gēn māo yǒu shénme guānxi?`,en:`Mom, the name giant panda is strange. What do they have to do with cats?`,th:`แม่ ชื่อแพนด้ายักษ์แปลกจัง มันเกี่ยวอะไรกับแมว?`,visual:o(`跟猫有什么关系`,`เกี่ยวอะไรกับแมว`,`30% center`)}),a(l,{role:`B`,speaker:`王一雪`,hanzi:`这个问题问得好，它们跟猫没什么关系，其实应该叫大猫熊。`,pinyin:`Zhège wèntí wèn de hǎo, tāmen gēn māo méi shénme guānxi, qíshí yīnggāi jiào dàmāoxióng.`,en:`Good question. They have little to do with cats; actually, they should be called big bear-cats.`,th:`ถามดี มันแทบไม่เกี่ยวกับแมว ที่จริงควรเรียกต้ามาวสยง`,visual:o(`其实应该叫大猫熊`,`ที่จริงควรเรียกต้ามาวสยง`,`70% center`)}),a(l,{role:`A`,speaker:`刘小明`,hanzi:`大熊猫为什么只吃竹子不吃肉？`,pinyin:`Dàxióngmāo wèishénme zhǐ chī zhúzi bù chī ròu?`,en:`Why do giant pandas eat only bamboo and not meat?`,th:`ทำไมแพนด้ายักษ์กินแต่ไผ่ ไม่กินเนื้อ?`,visual:o(`只吃竹子`,`กินแต่ไผ่`,`32% center`)}),a(l,{role:`B`,speaker:`王一雪`,hanzi:`它们跟人一样，也可以吃肉，但是对肉不感兴趣。`,pinyin:`Tāmen gēn rén yíyàng, yě kěyǐ chī ròu, dànshì duì ròu bù gǎn xìngqù.`,en:`Like people, they can eat meat, but they are not interested in it.`,th:`เหมือนคน มันกินเนื้อได้ แต่ไม่สนใจเนื้อ`,visual:o(`对肉不感兴趣`,`ไม่สนใจเนื้อ`,`68% center`)}),a(l,{role:`A`,speaker:`刘小明`,hanzi:`大熊猫为什么是中国的国宝？`,pinyin:`Dàxióngmāo wèishénme shì Zhōngguó de guóbǎo?`,en:`Why are giant pandas a Chinese national treasure?`,th:`ทำไมแพนด้ายักษ์เป็นสมบัติของชาติจีน?`,visual:o(`中国的国宝`,`สมบัติของชาติจีน`,`34% center`)}),a(l,{role:`B`,speaker:`王一雪`,hanzi:`全世界只有中国有野生大熊猫，中国是大熊猫的家。`,pinyin:`Quán shìjiè zhǐyǒu Zhōngguó yǒu yěshēng dàxióngmāo, Zhōngguó shì dàxióngmāo de jiā.`,en:`Only China has wild giant pandas. China is their home.`,th:`ทั่วโลกมีแพนด้ายักษ์ป่าเฉพาะในจีน จีนคือบ้านของแพนด้า`,visual:o(`只有中国有野生大熊猫`,`มีแพนด้าป่าเฉพาะในจีน`,`66% center`)}),a(l,{role:`A`,speaker:`刘小明`,hanzi:`我听说有的熊猫出国了，他们去哪儿了？`,pinyin:`Wǒ tīngshuō yǒude xióngmāo chūguó le, tāmen qù nǎr le?`,en:`I heard some pandas went abroad. Where did they go?`,th:`ได้ยินว่าแพนด้าบางตัวไปต่างประเทศ พวกมันไปไหน?`,visual:o(`熊猫出国了`,`แพนด้าไปต่างประเทศ`,`36% center`)}),a(l,{role:`B`,speaker:`王一雪`,hanzi:`关于这个问题，我得慢慢给你讲。`,pinyin:`Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng.`,en:`About that question, I will have to explain it slowly.`,th:`เกี่ยวกับคำถามนี้ แม่ต้องค่อย ๆ อธิบาย`,visual:o(`关于这个问题`,`เกี่ยวกับคำถามนี้`,`64% center`)}),a(l,{role:`C`,speaker:`刘小雪`,hanzi:`弟弟，你真是“十万个为什么”。`,pinyin:`Dìdi, nǐ zhēn shì shí wàn ge wèishénme.`,en:`Little brother, you really are a hundred thousand whys.`,th:`น้อง เธอเป็นเจ้าหนูจำไมจริง ๆ`,visual:o(`十万个为什么`,`เจ้าหนูจำไม`,`40% center`)})],qte:{after:3,prompt:{zh:`大熊猫为什么是中国的国宝？`,th:`ทำไมแพนด้ายักษ์เป็นสมบัติของชาติจีน?`,en:`Why are giant pandas a Chinese national treasure?`},options:[{value:`只有中国有野生大熊猫`,zh:`只有中国有野生大熊猫`,pinyin:`zhǐyǒu Zhōngguó yǒu yěshēng dàxióngmāo`,th:`มีแพนด้าป่าเฉพาะในจีน`},{value:`它们只吃竹子`,zh:`它们只吃竹子`,pinyin:`tāmen zhǐ chī zhúzi`,th:`มันกินแต่ไผ่`},{value:`名字很奇怪`,zh:`名字很奇怪`,pinyin:`míngzi hěn qíguài`,th:`ชื่อแปลกมาก`}],correct:`只有中国有野生大熊猫`,evidence:`王一雪：全世界只有中国有野生大熊猫。`,evidenceTh:`หวังอี้เสวี่ย: ทั่วโลกมีแพนด้าป่าเฉพาะในจีน`,sourceRef:l},builder:{prompt:{zh:`重组“关于”句`,th:`เรียงประโยคที่ใช้ 关于`,en:`Rebuild the 关于 sentence`},answer:[`关于这个问题`,`我得`,`慢慢`,`给你讲`],tiles:[`给你讲`,`慢慢`,`我得`,`关于这个问题`],gloss:{关于这个问题:`เกี่ยวกับคำถามนี้`,我得:`ฉันต้อง`,慢慢:`ค่อย ๆ`,给你讲:`อธิบายให้เธอฟัง`},translationTh:`เกี่ยวกับคำถามนี้ ฉันต้องค่อย ๆ อธิบายให้เธอฟัง`,translationEn:`I will have to explain this question slowly.`,evidence:`Text 2 · หน้าเล่ม 147`,sourceRef:l}},{id:`h3l16-panda-house`,number:`03`,glyph:`熊`,title:`熊猫每天做什么`,titleTh:`แพนด้าทำอะไรทุกวัน`,titleEn:`What pandas do every day`,place:`熊猫馆`,placeTh:`อาคารแพนด้า`,...i(`panda-house`),source:`Text 3 · หน้าเล่ม 148–149 · PDF หน้า 160–161`,sourcePage:`148-149`,sourceRef:u,imageAlt:{zh:`熊猫馆大熊猫`,th:`แพนด้ายักษ์ในอาคารแพนด้า`,en:`Giant pandas at the Panda House`},context:`在熊猫馆，王一雪和孩子们在看大熊猫。`,contextTh:`ในอาคารแพนด้า หวังอี้เสวี่ยกับลูก ๆ กำลังดูแพนด้า`,contextEn:`At the Panda House, Wang Yixue and the children watched giant pandas.`,characters:[{role:`A`,profile:`liuXiaoxue`,noteZh:`观察熊猫的孩子`,noteTh:`เด็กที่สังเกตแพนด้า`,noteEn:`The child observing pandas`},{role:`B`,profile:`wang`,noteZh:`解释熊猫习惯的妈妈`,noteTh:`แม่ที่อธิบายนิสัยแพนด้า`,noteEn:`The mother explaining panda behavior`},{role:`C`,profile:`liuXiaoming`,noteZh:`觉得熊猫舒服的孩子`,noteTh:`เด็กที่คิดว่าแพนด้าสบาย`,noteEn:`The child admiring their life`}],lines:[a(u,{role:`A`,speaker:`刘小雪`,hanzi:`这只大熊猫一会儿爬上去，一会儿跳下来，可爱极了！`,pinyin:`Zhè zhī dàxióngmāo yíhuìr pá shàngqu, yíhuìr tiào xiàlai, kě'ài jí le!`,en:`This panda climbs up one moment and jumps down the next. It is extremely cute!`,th:`แพนด้าตัวนี้เดี๋ยวปีนขึ้น เดี๋ยวกระโดดลง น่ารักมาก!`,visual:o(`一会儿爬一会儿跳`,`เดี๋ยวปีนเดี๋ยวกระโดด`,`30% center`)}),a(u,{role:`B`,speaker:`王一雪`,hanzi:`它好像还没吃饱，站起来张着嘴找吃的呢。`,pinyin:`Tā hǎoxiàng hái méi chī bǎo, zhàn qǐlai zhāngzhe zuǐ zhǎo chī de ne.`,en:`It seems not to be full yet. It stands with its mouth open looking for food.`,th:`ดูเหมือนมันยังไม่อิ่ม ยืนอ้าปากหาอาหารอยู่`,visual:o(`张着嘴找吃的`,`อ้าปากหาอาหาร`,`70% center`)}),a(u,{role:`A`,speaker:`刘小雪`,hanzi:`它身边那只熊猫半天没动，是不是在睡觉呢？`,pinyin:`Tā shēnbiān nà zhī xióngmāo bàntiān méi dòng, shì bú shì zài shuìjiào ne?`,en:`The panda beside it has not moved for a long while. Is it sleeping?`,th:`แพนด้าข้าง ๆ ไม่ขยับตั้งนาน กำลังนอนอยู่หรือเปล่า?`,visual:o(`半天没动`,`ไม่ขยับตั้งนาน`,`32% center`)}),a(u,{role:`B`,speaker:`王一雪`,hanzi:`我看不见它的脸，可能是吧。一般来说，熊猫每天要睡很多次觉。`,pinyin:`Wǒ kàn bu jiàn tā de liǎn, kěnéng shì ba. Yìbān lái shuō, xióngmāo měitiān yào shuì hěn duō cì jiào.`,en:`I cannot see its face, so perhaps. Generally speaking, pandas sleep many times a day.`,th:`แม่ไม่เห็นหน้า อาจใช่ โดยทั่วไปแพนด้านอนหลายครั้งต่อวัน`,visual:o(`一般来说`,`โดยทั่วไป`,`68% center`)}),a(u,{role:`A`,speaker:`刘小雪`,hanzi:`对，除了睡觉以外，很多时间都在吃东西。`,pinyin:`Duì, chúle shuìjiào yǐwài, hěn duō shíjiān dōu zài chī dōngxi.`,en:`Right. Besides sleeping, they spend much of their time eating.`,th:`ใช่ นอกจากนอนแล้ว เวลาส่วนใหญ่ก็กินอาหาร`,visual:o(`很多时间都在吃东西`,`เวลาส่วนใหญ่กินอาหาร`,`34% center`)}),a(u,{role:`C`,speaker:`刘小明`,hanzi:`大熊猫的生活真舒服啊！`,pinyin:`Dàxióngmāo de shēnghuó zhēn shūfu a!`,en:`A giant panda's life is so comfortable!`,th:`ชีวิตแพนด้าสบายจริง ๆ!`,visual:o(`生活真舒服`,`ชีวิตสบายจริง ๆ`,`66% center`)}),a(u,{role:`A`,speaker:`刘小雪`,hanzi:`妈妈，您帮我和这两只大熊猫照一张照片吧。`,pinyin:`Māma, nín bāng wǒ hé zhè liǎng zhī dàxióngmāo zhào yì zhāng zhàopiàn ba.`,en:`Mom, please take a photo of me with these two pandas.`,th:`แม่ ช่วยถ่ายรูปหนูกับแพนด้าสองตัวนี้หน่อย`,visual:o(`照一张照片`,`ถ่ายรูปหนึ่งใบ`,`40% center`)})],qte:{after:3,prompt:{zh:`一般来说，大熊猫每天做什么？`,th:`โดยทั่วไป แพนด้าทำอะไรทุกวัน?`,en:`Generally speaking, what do giant pandas do every day?`},options:[{value:`睡很多次觉`,zh:`睡很多次觉`,pinyin:`shuì hěn duō cì jiào`,th:`นอนหลายครั้ง`},{value:`一直爬树`,zh:`一直爬树`,pinyin:`yìzhí pá shù`,th:`ปีนต้นไม้ตลอด`},{value:`跟人拍照`,zh:`跟人拍照`,pinyin:`gēn rén pāizhào`,th:`ถ่ายรูปกับคน`}],correct:`睡很多次觉`,evidence:`王一雪：一般来说，熊猫每天要睡很多次觉。`,evidenceTh:`หวังอี้เสวี่ย: โดยทั่วไปแพนด้านอนหลายครั้งต่อวัน`,sourceRef:u},builder:{prompt:{zh:`重组“一般来说”句`,th:`เรียงประโยคบอกภาพรวม`,en:`Rebuild the generalization`},answer:[`一般来说`,`熊猫每天`,`要睡`,`很多次觉`],tiles:[`很多次觉`,`一般来说`,`要睡`,`熊猫每天`],gloss:{一般来说:`โดยทั่วไป`,熊猫每天:`แพนด้าทุกวัน`,要睡:`ต้องนอน`,很多次觉:`หลายครั้ง`},translationTh:`โดยทั่วไป แพนด้านอนหลายครั้งต่อวัน`,translationEn:`Generally speaking, pandas sleep many times a day.`,evidence:`Text 3 · หน้าเล่ม 149`,sourceRef:u}}],p={id:`hsk3-l16`,slug:`lesson-16`,level:`hsk3`,number:16,featured:!1,sourceRef:r,source:{title:`新HSK教程 3 · New HSK Course 3`,lesson:`Lesson 16 · 我听说有的熊猫出国了`,printedPages:`144–153`,pdfPages:`156–165`,file:`hsk3.pdf`,sourceRef:r},title:{zh:`我听说有的熊猫出国了`,pinyin:`Wǒ tīngshuō yǒude xióngmāo chūguó le`,en:`I heard some pandas went abroad`,thAid:`ฉันได้ยินว่าแพนด้าบางตัวไปต่างประเทศแล้ว`},summary:{zh:`谈宠物领养、大熊猫知识和动物的生活习惯。`,en:`Discuss pet adoption, giant panda facts, and animal habits.`,thAid:`พูดคุยเรื่องการรับเลี้ยงสัตว์ ความรู้เกี่ยวกับแพนด้า และนิสัยของสัตว์`},translationPolicy:{kind:`editorial-aid`,labelTh:`คำแปลไทยเพื่อช่วยเรียน เรียบเรียงจากต้นฉบับ`},objectives:[{zh:`能听懂并描述动物的特征、习性和生活环境。`,en:`Be able to understand and describe the characteristics, habits, and habitats of animals.`,thAid:`ฟังเข้าใจและบรรยายลักษณะ นิสัย และถิ่นอาศัยของสัตว์`,sourceRef:n(`144`,`156`)},{zh:`能听懂并表达个人对动物的看法。`,en:`Be able to understand and express personal opinions about animals.`,thAid:`ฟังเข้าใจและแสดงความคิดเห็นส่วนตัวเกี่ยวกับสัตว์`,sourceRef:n(`144`,`156`)},{zh:`掌握比较句（11）的用法，能表达事物在数量或时间上的差异。`,en:`Master comparative sentences (11) to express differences in quantity or time.`,thAid:`ใช้ประโยคเปรียบเทียบแบบที่ 11 เพื่อบอกความแตกต่างด้านจำนวนหรือเวลา`,sourceRef:n(`144`,`156`)},{zh:`了解大熊猫的基本情况。`,en:`Gain a basic understanding of giant pandas.`,thAid:`เรียนรู้ข้อมูลพื้นฐานเกี่ยวกับแพนด้ายักษ์`,sourceRef:n(`144`,`156`)}],contents:[{number:`00`,title:`目标与热身`,titleTh:`เป้าหมายและการเตรียมบท`,detail:`Objectives · Warm-Up`,pages:`144`,route:`/home/hsk3/lesson-16/preface/`,sourceRef:n(`144`,`156`)},{number:`01`,title:`小猫认得我们`,titleTh:`ลูกแมวจำพวกเราได้`,detail:`Text 1 · New Words 1–10`,pages:`145–146`,scene:1,sourceRef:c},{number:`02`,title:`大熊猫是国宝`,titleTh:`แพนด้ายักษ์คือสมบัติของชาติ`,detail:`Text 2 · New Words 11–18`,pages:`147–148`,scene:2,sourceRef:n(`147-148`,`159-160`)},{number:`03`,title:`熊猫每天做什么`,titleTh:`แพนด้าทำอะไรทุกวัน`,detail:`Text 3 · New Words 19–24`,pages:`148–150`,scene:3,sourceRef:n(`148-150`,`160-162`)},{number:`04`,title:`练习与活动`,titleTh:`แบบฝึกและกิจกรรม`,detail:`Exercises · Activity`,pages:`151–153`,sourceRef:n(`151-153`,`163-165`)}],vocabulary:s,grammarFocus:[{title:`并列复句“一会儿……，一会儿……”`,titleEn:`Coordinate sentence 一会儿……一会儿……`,explanationZh:`表示短时间内发生的不同动作，或者一种对立的情况。`,explanationEn:`The pattern marks different actions in a short period or alternating states.`,thAid:`บอกการกระทำหรือสภาพที่สลับกันในช่วงเวลาสั้น ๆ`,examples:[`它一会儿在你脚边睡觉，一会儿在你身上爬。`,`最近天气一会儿冷，一会儿热。`],sourceRef:n(`146`,`158`)},{title:`介词“关于”`,titleEn:`Preposition 关于`,explanationZh:`后面加名词，引出涉及的对象或话题。`,explanationEn:`关于 is followed by a noun to introduce a topic or subject.`,thAid:`ตามด้วยคำนามเพื่อเกริ่นหัวข้อหรือสิ่งที่กล่าวถึง`,examples:[`关于这个问题，我得慢慢给你讲。`,`关于比赛的时间，我明天告诉大家。`],sourceRef:n(`148`,`160`)},{title:`固定短语“一般来说”`,titleEn:`Set phrase 一般来说`,explanationZh:`表示大多数情况如此，常用在句子开头。`,explanationEn:`This phrase means generally speaking and often begins a sentence.`,thAid:`ใช้บอกว่าส่วนใหญ่เป็นเช่นนั้น มักวางต้นประโยค`,examples:[`一般来说，熊猫每天要睡很多次觉。`,`一般来说，学习外语需要多练习。`],sourceRef:n(`149`,`161`)}],characters:d,scenes:f};export{p as LESSON_HSK3_L16};